INSERT INTO SPD_PRODUCT_CATALOG (ID, IS_ACTIVE, CODE, NAME, DESCRIPTION, UNITS_NAME, PARENT_ID, IS_PRINCIPAL, IS_NATIONAL, IS_TERRITORIAL, IS_LEAF, CREATED_AT, UPDATED_AT) VALUES (
  1247,
  'S',
  '2701029',
  'Salas de audiencia con reforzamiento estructural',
  'Se refiere a las obras necesarias para intervenir o reforzar la estructura de Edificios de Salas de Audiencias o Salas de Audiencia, con el objeto de acondicionarlos a niveles adecuados de seguridad sismo resistente de acuerdo con los requisitos de la Ley 400 de 1997, sus decretos reglamentarios, o las normas que los adicionen, modifiquen o sustituyan y el Reglamento Colombiano de Construcción sismo resistente y la norma que lo adicione, modifique o sustituya. Salas de audiencia:Espacio destinado  para el desarrollo de audiencias de juzgamiento, conformadas por el estrado (compuesto de un puesto para Juez y uno para el secretario); el área central (las partes, el testigo, Fiscalía, Defensoría, Procuraduría, Ministerio Público); y,  un área para el  público.',
  NULL,
  139,
  NULL,
  NULL,
  NULL,
  'N',
  TIMESTAMP '2026-11-12 13:59:23.352514 +00:00',
  TIMESTAMP '2026-11-12 13:59:23.352514 +00:00');
