  1248,
  'S',
  '2701025',
  'Salas de audiencia adecuadas y dotadas',
  'Se refiere a las obras necesarias para cambiar o variar el diseño de una Sala de Audiencia, o de un edificio de Salas de Audiencia, o parte de él, incluyendo reparaciones locativas,  garantizando la permanencia total o parcial del inmueble original. Salas de audiencia:Espacio destinado  para el desarrollo de audiencias de juzgamiento, conformadas por el estrado (compuesto de un puesto para Juez y uno para el secretario); el área central (las partes, el testigo, Fiscalía, Defensoría, Procuraduría, Ministerio Público); y,  un área para el  público.',
  NULL,
  139,
  NULL,
  NULL,
  NULL,
  'N',
  TIMESTAMP '2026-11-12 13:59:23.352514 +00:00',
  TIMESTAMP '2026-11-12 13:59:23.352514 +00:00');
INSERT INTO SPD_PRODUCT_CATALOG (ID, IS_ACTIVE, CODE, NAME, DESCRIPTION, UNITS_NAME, PARENT_ID, IS_PRINCIPAL, IS_NATIONAL, IS_TERRITORIAL, IS_LEAF, CREATED_AT, UPDATED_AT) VALUES (
  1249,
  'S',
  '2701023',
  'Despachos judiciales con reforzamiento estructural',
  'Se refiere a las obras necesarias para intervenir o reforzar la estructura de uno o varios Despachos Judiciales, con el objeto de acondicionarlos a niveles adecuados de seguridad sismo resistente de acuerdo con los requisitos de la Ley 400 de 1997, sus decretos reglamentarios, o las normas que los adicionen, modifiquen o sustituyan y el Reglamento Colombiano de Construcción sismo resistente y la norma que lo adicione, modifique o sustituya. Lugar donde se lleva a cabo la misionalidad de administrar justicia. Sede de Despachos Judiciales: Edificación  en la cual se realiza el proceso de administración de justicia y agrupa varios juzgados.',
