  'Se refiere a las obras tendientes a recuperar y adaptar un Despacho Judicial o parte de este, con el fin de conservar y revelar sus valores estéticos, históricos y simbólicos. Se fundamenta en el respeto por su integridad y autenticidad; incluyendo las liberaciones o demoliciones parciales de agregados de los bienes de inetrés culturas, aprobadas por la autoridad competente. Sede de Despachos Judiciales: Edificación  en la cual se realiza el proceso de administración de justicia y agrupa varios juzgados.',
