  1627,
  'S',
  '3301055',
  'Servicio de apoyo financiero para el desarrollo de prácticas artísticas y culturales',
  'El Ministerio de Cultura, a través del Programa Nacional de Estímulos tiene como propósito movilizar a los agentes del sector, bien sea en el ámbito nacional o internacional, para que en las más diversas disciplinas, reciban a través de becas, pasantías, premios nacionales, reconocimientos o residencias artísticas un apoyo a su quehacer. Este Programa está dirigido principalmente a personas naturales y el mecanismo dispuesto para acceder a dichos estímulos es a través de convocatorias públicas anuales, de manera que puedan participar de ese abanico de oportunidades todos los actores del sector cultural.',
  NULL,
  155,
  NULL,
  NULL,
