  1647,
  'S',
  '3301051',
  'Servicio de educación informal al sector artístico y cultural',
  'Son las capacitaciones para fortalecer las competencias y la calidad de los conocimientos de creadores de contenidos culturales mediáticos, de gestores y agentes culturales, de bibliotecarios, de músicos, de agentes que trabajan con la primera infancia, agentes del campo literario y el libro y agentes del campo de artes visuales y plásticas. La educación informal hace referencia a la adquisición del aprendizaje y todo tipo de conocimiento libre y espontáneo, proveniente de personas, entidades, medios masivos de comunicación, medios impresos, tradiciones, costumbres, comportamientos sociales y otros no estructurados. Incluye charlas, talleres, cursos no certificados.',
  NULL,
  155,
  NULL,
  NULL,
  NULL,
  'N',
