  'Corresponde a la generación de condiciones para la creación, gestión, producción, difusión, circulación y apropiación de las prácticas artísticas y contenidos culturales mediáticos. Incluye la creación de obras, coproducciones y la producción y circulación de exhibiciones, de los agentes del sector artístico y cultural, así como la circulación de contenidos culturales mediáticos apoyados por el Ministerio de Cultura.',
